/// <reference types="@workadventure/iframe-api-typings" />
// Campus M@N - carte habillee (genere par build_campus_habille.py, ne pas editer a la main)
import { bootstrapExtra } from "@workadventure/scripting-api-extra";

const DESTINATIONS = [
  { id: 'entree', label: "Entrée du campus", x: 1936, y: 2928 },
  { id: 'auditorium', label: "Auditorium", x: 624, y: 1264 },
  { id: 'bureau', label: "Bureau virtuel M@N", x: 1936, y: 976 },
  { id: 'center', label: "M@N Center", x: 3280, y: 1200 },
  { id: 'candidat', label: "Espace Candidat", x: 496, y: 2768 },
  { id: 'client', label: "Espace Client", x: 1072, y: 2832 },
  { id: 'institut', label: "Institut M@N", x: 2640, y: 2832 },
  { id: 'formation', label: "Formation hybride", x: 3344, y: 3056 }
];
const BORNES = ["entree", "auditorium", "bureau", "center", "candidat", "client", "institut", "formation"];
const FERMES = ["auditorium", "center", "client", "institut", "formation"];
const NOMS: Record<string, string> = {"entree": "Entrée du campus", "auditorium": "Auditorium", "bureau": "Bureau virtuel M@N", "center": "M@N Center", "candidat": "Espace Candidat", "client": "Espace Client", "institut": "Institut M@N", "formation": "Formation hybride"};
const LIEUX: Record<string, string> = {"clairiere": "La clairière : un salon en plein air pour discuter.", "potager": "Le potager partagé du campus.", "belvedere": "Le belvédère : la plus belle vue sur le lac.", "amphi_verdure": "L'amphithéâtre de verdure.", "pique_nique": "L'aire de pique-nique."};

let popup: any = undefined;
let message: any = undefined;
function fermer() {
  if (popup) { popup.close(); popup = undefined; }
  if (message) { message.remove(); message = undefined; }
}

WA.onInit().then(() => {
  for (const b of BORNES) {
    WA.room.area.onEnter('borne_' + b).subscribe(() => {
      fermer();
      const boutons: any[] = DESTINATIONS.filter(d => d.id !== b).map(d => ({
        label: d.label, className: 'primary', callback: () => { fermer(); WA.player.teleport(d.x, d.y); }
      }));
      boutons.push({ label: 'Fermer', className: 'normal', callback: () => fermer() });
      popup = WA.ui.openPopup('popup_' + b, 'Borne M@N : où voulez-vous aller ?', boutons);
    });
    WA.room.area.onLeave('borne_' + b).subscribe(fermer);
  }
  for (const b of FERMES) {
    WA.room.area.onEnter('bientot_' + b).subscribe(() => {
      fermer();
      message = WA.ui.displayActionMessage({ message: NOMS[b] + ' : bientôt disponible', callback: () => {} });
    });
    WA.room.area.onLeave('bientot_' + b).subscribe(fermer);
  }
  for (const k of Object.keys(LIEUX)) {
    WA.room.area.onEnter('lieu_' + k).subscribe(() => {
      fermer();
      message = WA.ui.displayActionMessage({ message: LIEUX[k], callback: () => {} });
    });
    WA.room.area.onLeave('lieu_' + k).subscribe(fermer);
  }
  WA.room.area.onEnter('accueil').subscribe(() => {
    fermer();
    popup = WA.ui.openPopup('popup_accueil', 'Bienvenue au Campus M@N ! Les bornes @ orange vous emmènent directement devant chaque bâtiment.', [
      { label: 'Merci', className: 'primary', callback: () => fermer() }]);
  });
  WA.room.area.onLeave('accueil').subscribe(fermer);
  bootstrapExtra().catch(e => console.error(e));
}).catch(e => console.error(e));

export {};
